        slow_exc.response_body = json.dumps({"error": "slow_down"}).encode()
        tokens = {"access_token": "at"}
        mock_kc.token.side_effect = [slow_exc, tokens]
        mock_time.monotonic.side_effect = [0, 1, 2]
